INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 7, 'theory', 'Quiz: iterating over and copying lists');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 0, 'What does the first pair give in the loop for i, x in enumerate(["a", "b"], start=1)?', '["i = 0, x = \"a\"", "i = 1, x = \"b\"", "i = 1, x = \"a\"", "i = 0, x = \"b\""]', 2, 'enumerate yields "index, item" pairs; start=1 begins counting at one, and the first item is "a".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 1, 'How many passes does the loop for a, b in zip([1, 2, 3], [10, 20]) make?', '["3", "2", "5", "Raises an error"]', 1, 'zip stops at the shortest list, so the extra element of the longer one is silently dropped.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 2, 'a = [1, 2, 3]; b = a; b.append(4). What is the list a?', '["[1, 2, 3, 4]", "[1, 2, 3]", "[4]", "An error"]', 0, 'b = a does not copy: one list simply has two names, so a change through b is visible in a too.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 3, 'Which expression creates a real (independent) copy of the list a?', '["b = a", "b = [a]", "b = a is a", "b = a[:]"]', 3, 'The full slice a[:] (like a.copy() and list(a)) builds a new list; b = a only hangs a second name on the same one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 4, 'grid = [[0] * 3] * 3; grid[0][0] = 7. What is grid[1][0]?', '["0", "7", "None", "An error"]', 1, 'The outer multiplication repeated a reference to the same row, so all three rows changed.');
